LESSON = dict(
 id=10, title="Search strategies: Boolean logic, vocabulary, translation and documentation",
 time_min=100, version="0.1.0", status="AI-drafted; awaiting qualified human expert review", content_type="Established practice; database syntax must be checked against official documentation",
 last_verified="2026-11-26 (PRESS 2016 and PRISMA-S 2021 verified bibliographically via Crossref; examples from real PubMed searches that day)",
 prerequisites=["Modules 4 and 5"],
 objectives=["Build a structured search from concepts, synonyms and controlled vocabulary.","Use Boolean operators, parentheses, truncation and field tags correctly.","Read and critique a database's query translation.","Balance sensitivity and precision and test a strategy against known items.","Document searches reproducibly (PRISMA-S) and request peer review (PRESS)."],
 why="A review can only synthesise what it finds. Missed studies bias results; undocumented searches cannot be reproduced.",
 plain="""Build a search from **concepts**, not sentences. For each PICO element list synonyms, then combine: **OR** inside a concept (widens), **AND** between concepts (narrows), **NOT** rarely (it can remove relevant records). Use **parentheses** to control grouping.
Example for flies: (Drosophila OR 'fruit fly' OR 'fruit flies') AND (exercise OR 'physical activity' OR 'climbing training') AND (lifespan OR longevity OR 'life span').
**Truncation** (e.g. exercis*) captures word endings (syntax differs by database; some PubMed tools do not accept wildcards). **Field tags** restrict where a term must appear ([ti] title, [tiab] title/abstract, [pt] publication type in PubMed). **Controlled vocabulary** (MeSH in PubMed/MEDLINE, Emtree in Embase) groups synonyms but lags for new topics - combine it with free text.""",
 intermediate="""**Sensitivity vs precision.** Sensitivity (recall) = proportion of all relevant records your search retrieves; precision = proportion of retrieved records that are relevant. Systematic reviews favour sensitivity, then screen. Typical precision is low.
**Database translation.** A strategy must be rewritten for each database: field tags, vocabulary, truncation, proximity operators, and limits differ. Never paste one database's syntax into another.
**Query translation (PubMed).** PubMed expands terms (automatic term mapping) and shows the translation. Example, real (2026-11-26): 'dietary restriction lifespan model organisms systematic review' returned **0** because every word became an ANDed concept including 'model' and 'organ'; the structured query (Drosophila) AND (lifespan OR longevity) AND (dietary restriction OR diet) returned **869** records. Another real example: 'STEM education' was translated into *plant stems* and *scanning transmission electron microscopy*.
**Nomenclature.** Include scientific and common names, alternative spellings, historical and symbol gene names, taxonomic synonyms.
**Supplementary methods.** Citation chasing, reference lists, trial/preprint registries, grey literature; document each.
**Peer review and reporting.** PRESS (McGowan et al. 2016) is a guideline for peer review of electronic search strategies; PRISMA-S (Rethlefsen et al. 2021) is a reporting extension for literature searches. Record database, platform, date, full query, limits, number retrieved.""",
 advanced="""Validated search filters (e.g. for study design) trade sensitivity for precision and may not exist for animal or ecological studies; treat them as options to test, not truths. Evaluate your strategy with a **benchmark set** (reference lists of known reviews): sensitivity = retrieved/benchmark. Iteratively add terms from missed records ('word frequency analysis'). Deduplicate carefully afterwards (Module 14); do not rely on one database's coverage. For living reviews, store the strategy and rerun by date range with documented overlap handling. Machine-assisted screening can prioritise but not replace a comprehensive search.""",
 formulas=[dict(name="Sensitivity and precision", tex=r"\text{Sensitivity}=\frac{TP}{TP+FN},\quad \text{Precision}=\frac{TP}{TP+FP}", symbols={"TP":"relevant records retrieved","FN":"relevant records missed","FP":"irrelevant records retrieved"})],
 assumptions=["A benchmark of known relevant records exists independent of the query.","Query syntax matches the target database's documentation.","Search dates and results are recorded at the time of search."],
 worked_example="""Benchmark of 12 known relevant papers. Strategy A retrieves 2,000 records, containing 9 of the 12 and (after screening) 40 total relevant records. Sensitivity on benchmark = 9/12 = **75%**; precision (from screening) = 40/2000 = **2%**. Adding 'fruit fly' and a gene-symbol synonym retrieves 2,600 records and 11/12 benchmark items (sensitivity **92%**), with 47 relevant records now found after screening, precision is 47/2600 = 1.8%. Is the extra workload justified? In a systematic review usually yes - and you document the change as a new search *version* with date.""",
 examples=[("Clinical","MeSH 'Diabetes Mellitus, Type 2' + free text; RCT filter validated for MEDLINE."),("Plant","Latin binomials plus common crop names; AGRICOLA/CAB Abstracts if accessible."),("Microbiology","Species names changed by taxonomy: include old and new genus names."),("Ecology","Include taxon synonyms and non-English terms; consult CEE guidance."),("Education","ERIC thesaurus + free text; 'STEM' ambiguity in PubMed.")],
 mistakes=["Typing a sentence into the search box.","Using NOT to exclude humans and losing relevant records.","No synonyms.","Not reading the query translation.","Pasting syntax across databases.","Not recording the search date.","Searching one database."],
 misconceptions=[("'More results means a better search.'","Relevance matters: measure sensitivity on a benchmark."),("'MeSH is enough.'","Recent or niche terms are not yet indexed; combine with free text.")],
 controversies=["Value of search filters outside clinical trials.","How many databases are enough.","Role of Google Scholar in systematic searching."],
 decision_tree=[("Concepts defined with synonyms?","No -> build a concept table first."),("Controlled vocabulary + free text?","If only one, add the other."),("Tested on a benchmark set?","If sensitivity is low, add terms from missed records."),("Peer reviewed (PRESS) and documented (PRISMA-S)?","Do before running final searches.")],
 exercises=["Build a concept table for your question with >=5 synonyms for each concept.","Run your structured query in PubMed, read the translation, and log it in the Search Log; then run a free-text sentence version and compare counts.","Assemble a 10-item benchmark and compute sensitivity for two versions of your strategy."],
 coding=dict(r='# Count records returned by a PubMed query with rentrez (requires internet; run yourself)\n# install.packages("rentrez"); library(rentrez)\n# r <- entrez_search(db="pubmed", term="(Drosophila) AND (lifespan OR longevity) AND (dietary restriction OR diet)")\n# r$count   # compare with the Search Log; record the date\n', python='# Sensitivity/precision from counts\ntp, fn, fp = 40, 7, 1960   # screening results of strategy A, illustrative\nprint(tp/(tp+fn), tp/(tp+fp))   # recall among known-relevant 0.85 (illustrative), precision 0.02'),
 integrity="Never claim a search was run unless it was. Report all databases searched including those with no yield. Do not tune a strategy to produce a desired result.",
 further=["mcgowan2016","rethlefsen2021","page2021ee","munn2018"],
 application="**First-paper task (Milestone 5):** finalise concept table; build database-specific strategies; get one person (librarian/mentor) to PRESS-review; run them yourself; log each (database, platform, date, exact query, counts) and save raw exports.",
 checklist=["Concept table with synonyms","Query translation read","Benchmark sensitivity computed","Peer review requested","All searches logged with dates and raw exports saved"],
 quiz=[
  dict(q="Which combination widens a search?", opts=["AND between synonyms","OR between synonyms within a concept","NOT","Adding more concepts"], ans=1, why="OR unions synonyms; AND intersects concepts."),
  dict(q="A benchmark set has 20 relevant records; your search retrieves 15 of them. Sensitivity?", opts=["15%","75%","25%","Cannot be computed"], ans=1, why="15/20 = 75%.", numeric=True),
  dict(q="Why can a sentence typed into PubMed return 0 results?", opts=["PubMed is down.","Automatic term mapping ANDs every term (including generic ones), so all must match.","Sentences are illegal.","MeSH is missing."], ans=1, why="Observed with the 'dietary restriction lifespan model organisms systematic review' example."),
  dict(q="PRISMA-S is...", opts=["A risk-of-bias tool","A reporting extension for literature searches","A statistical test","A database"], ans=1, why="Rethlefsen et al. 2021."),
  dict(q="What is a risk of using NOT?", opts=["None.","It can remove relevant records (e.g. NOT human removes studies that include humans and animals).","It widens the search.","It breaks syntax."], ans=1, why="NOT can silently exclude relevant records."),
 ])
